parameters.jsCode:
// Telegram hands back everything since next_offset and only forgets a message
// once we ask for the one after it, so the marker is advanced at the end of the
// run rather than here. Handling a message twice is harmless. Losing one is not.
const state = $('Load state').first().json;
const allow = new Map((state.allowlist || []).map(a => [String(a.telegram_user_id), a]));
const updates = ($input.first().json || {}).result || [];

const URL_RE = /https?:\/\/[^\s<>()]+/i;
let nextOffset = Number(state.next_offset) || 0;
const out = [];

for (const u of updates) {
  if (u.update_id >= nextOffset) nextOffset = u.update_id + 1;
  const msg = u.message;
  if (!msg || !msg.text) continue;

  const fromId = String(msg.from && msg.from.id);
  const who = allow.get(fromId) || null;
  const text = String(msg.text).trim();
  const found = text.match(URL_RE);
  const url = found ? found[0].replace(/[.,;:)\]]+$/, '') : null;
  // whatever the editor typed around the link: their own note, and the title
  // we fall back to when the page cannot be read
  const note = found ? text.replace(found[0], ' ').replace(/\s+/g, ' ').trim() : '';

  out.push({ json: {
    update_id: u.update_id,
    chat_id: msg.chat.id,
    from_id: fromId,
    from_name: [msg.from.first_name, msg.from.last_name].filter(Boolean).join(' '),
    allowed: !!who,
    text, url, note,
  }});
}

// Updates that carry nothing we handle still have to move the marker, or we
// would ask for them again every minute forever.
if (out.length === 0) {
  return updates.length ? [{ json: { skip: true, next_offset: nextOffset } }] : [];
}
for (const o of out) o.json.next_offset = nextOffset;
return out;

// Read the page for a title, so the editor does not have to type one.
//
// A page we cannot read leaves the editor's own words as the title instead.
// LinkedIn sits behind a login and lands here almost every time, and LinkedIn is
// the client's main social source, so this path is the normal one rather than
// the exception.
const m = $json;
if (m.skip || !m.allowed || !m.url) {
  return { json: { ...m, page_ok: false, title: null, publisher: null, published_at: null, text: '' } };
}

const unescape = s => String(s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

let page_ok = false, pageTitle = null, publisher = null, published_at = null, text = '';
try {
  const html = String(await this.helpers.httpRequest({
    url: m.url, timeout: 15000, json: false,
    headers: { 'User-Agent': 'DFP newsletter bot (HAMK student project)' },
  }));
  const pick = re => { const x = html.match(re); return x ? unescape(x[1]) : null; };
  pageTitle = pick(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)/i)
           || pick(/<title[^>]*>([^<]+)<\/title>/i);
  publisher = pick(/<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)/i);
  published_at = pick(/<meta[^>]+property=["']article:published_time["'][^>]+content=["']([^"']+)/i);
  // Sites append their own name to the <title>. The editor does not need it
  // twice, the publisher is already on the next line of the reply. Only a
  // tail that matches the site is removed, so a real title ending in a dash
  // survives.
  const host = (m.url.match(/^https?:\/\/(?:www\.)?([^\/]+)/i) || ['', ''])[1].split('.')[0];
  for (const name of [publisher, host].filter(Boolean)) {
    const esc = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (pageTitle) pageTitle = pageTitle.replace(new RegExp(`\\s*[\u2013\u2014|\u00b7-]\\s*${esc}\\s*$`, 'i'), '').trim();
  }

  // A page that loads is not the same as an article we can read. LinkedIn
  // answers with its login page, title and all, so trusting that would file
  // "LinkedIn Login, Sign in" as the headline of whatever the editor meant.
  const LOGIN_LIKE = /(log ?in|sign ?in|sign ?up|kirjaudu|rekister|access denied|just a moment|are you a robot)/i;
  if (pageTitle && LOGIN_LIKE.test(pageTitle)) pageTitle = null;
  page_ok = !!pageTitle;

  // The article itself. Without this the bot can file a link but never say
  // anything about it, which is most of what the editor wants.
  //
  // Start at the article container and run to whatever closes the article
  // region. Matching to the first </div> stops at the first nested one, which
  // on some pages left three sentences and a summary confidently about the
  // wrong thing. Paragraphs are preferred because they keep prose and drop
  // menus and buttons.
  let region = html;
  const start = html.search(/<div[^>]*class="[^"]*\bentry-content\b[^"]*"/i);
  if (start >= 0) {
    const after = html.slice(start);
    const end = after.search(/<footer|<\/article>|class="[^"]*(?:entry-footer|post-nav|sharedaddy|comments|related)/i);
    region = end > 0 ? after.slice(0, end) : after;
  }
  const stripped = region.replace(/<(script|style|noscript)[\s\S]*?<\/\1>/gi, ' ');
  const paras = [...stripped.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)]
    .map(x => unescape(x[1].replace(/<[^>]+>/g, ' ')))
    .filter(t => t.length > 40);
  const byParas = paras.join('\n');
  const byStrip = unescape(stripped.replace(/<[^>]+>/g, ' '));
  text = (byParas.length > 200 ? byParas : byStrip).slice(0, 6000);
} catch (e) {
  page_ok = false;
}

return { json: { ...m, page_ok, publisher, published_at, text,
                 title: page_ok ? pageTitle : (m.note || null) } };

// Through the shared workflow, never a model call of our own, or the cost
// figures we give the client stop adding up.
const m = $('Fetch page').item.json;
return { json: {
  task: 'telegram_capture',
  item_id: $json.item_id,
  system_prompt: 'Tiivistä seuraava uutinen jäsenkirjeeseen kolmella lyhyellä suomenkielisellä lauseella. Kerro vain se mitä tekstissä lukee. Älä keksi mitään lisää.',
  user_text: `${m.title}\n\n${m.text}`,
} };

// Tell the editor what happened, in their words rather than ours.
//
// Nothing is read from $json here: the two branches of "Worth summarising"
// arrive carrying different things, so every value is fetched from the node
// that owns it.
const m  = $('Fetch page').item.json;    // the message and the page
const db = $('Save capture').item.json;  // what the database did
let llm = null;
try { llm = $('Summarise').item.json; } catch (e) { llm = null; }  // only one branch summarises

const cost = (llm && llm.cost_eur != null) ? Number(llm.cost_eur) : null;
const tokens = llm ? (Number(llm.tokens_in || 0) + Number(llm.tokens_out || 0)) : 0;

let reply = null;
if (m.skip) {
  reply = null;
} else if (!m.allowed) {
  // Telling an unknown sender their own id is how someone gets added without a
  // round trip. It gives away nothing: they can read it from any bot.
  reply = `I only take links from people on the list.\n\nYour Telegram ID is ${m.from_id}. Send that to Vinh and he will add you.`;
} else if (!m.url) {
  reply = 'Send me a link and I will save it for the newsletter. You can put a note after the link.';
} else if (!m.page_ok && !m.note) {
  reply = 'I could not read that page. Send the link again with a title after it and I will save that instead.';
} else if (db.item_id) {
  const lines = [`Saved: ${m.title}`];
  if (m.publisher) lines.push(m.publisher);
  if (llm && llm.text) {
    lines.push('', llm.text.trim());
    // What the client asked about in the kickoff, on their own article,
    // rather than as a number on a slide.
    lines.push('', `${tokens} tokens${cost != null ? ` · €${cost.toFixed(4)}` : ''}${cost === 0 ? ' (free tier)' : ''}`);
  } else if (!m.page_ok) {
    lines.push('', 'I could not read the page, so I used your own words as the title.');
  } else {
    lines.push('', 'Saved without a summary: there was too little text on the page.');
  }
  reply = lines.join('\n');
} else if (db.already_known) {
  reply = 'I already have that link.';
} else {
  reply = 'Something went wrong saving that. Try again, or tell Vinh.';
}

return { json: { ...m, reply, item_id: db.item_id ?? null, summarised: !!(llm && llm.text) } };

// Nothing to say for a message we did not act on.
const m = $json;
if (!m.reply) return { json: m };

await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`,
  body: { chat_id: m.chat_id, text: m.reply, disable_web_page_preview: true },
  json: true,
});
return { json: m };

